import{_ as p,a0 as l,w as o,s as d,I as i,x as e,a1 as a,A as t,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const z=JSON.parse('{"title":"使用 Python 调整图像大小 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Python 调整图像大小 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Python 调整图像大小 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Python 调整图像大小 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20210101 Resize images using Python","title":"使用 Python 调整图像大小","tag":"202101","desc":""},"relativePath":"202101/20210101 Resize images using Python.md","filePath":"[post].md"}'),g={name:"202101/20210101 Resize images using Python.md"};function h(m,s,u,f,b,y){const n=l("Link");return o(),d("div",null,[s[20]||(s[20]=i("h1",{id:"使用-python-调整图像大小",tabindex:"-1"},[e("使用 Python 调整图像大小 "),i("a",{class:"header-anchor",href:"#使用-python-调整图像大小","aria-label":"Permalink to “使用 Python 调整图像大小”"},"​")],-1)),s[21]||(s[21]=i("blockquote",null,[i("p",null,"快速解释如何在 Python 中调整图像大小，同时保持相同的长宽比。")],-1)),s[22]||(s[22]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/life-python.jpg?itok=F2PYP2wT",alt:"Python in a tree",title:"Python in a tree"})],-1)),i("p",null,[s[2]||(s[2]=e("我喜欢 ",-1)),a(n,{href:"http://python.org/",title:"Python Programming Language – Official Website"},{default:t(()=>[...s[0]||(s[0]=[e("Python",-1)])]),_:1}),s[3]||(s[3]=e("，而且我已经学了一段时间了。前段时间，我写了一个 Python 脚本，在这个脚本中，我需要调整一堆图片的大小，同时保持长宽比（比例）不变。于是我四处寻找，发现了 ",-1)),a(n,{href:"https://pypi.org/project/Pillow/",title:"Python Imaging Library"},{default:t(()=>[...s[1]||(s[1]=[e("Pillow",-1)])]),_:1}),s[4]||(s[4]=e("，这是一个 Python 图像库，也是一个叫做 PIL 的旧库的“友好复刻”。",-1))]),s[23]||(s[23]=r(`<p>要安装 Pillow，请使用 Python 的 <code>pip</code> 模块：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python3 -m pip install Pillow</span></span></code></pre></div><h3 id="按宽度缩放" tabindex="-1">按宽度缩放 <a class="header-anchor" href="#按宽度缩放" aria-label="Permalink to “按宽度缩放”">​</a></h3><p>这是一个使用 Pillow 模块来调整图片大小的基本脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from PIL import Image</span></span>
<span class="line"><span></span></span>
<span class="line"><span>basewidth = 300</span></span>
<span class="line"><span>img = Image.open(&#39;fullsized_image.jpg&#39;)</span></span>
<span class="line"><span>wpercent = (basewidth / float(img.size[0]))</span></span>
<span class="line"><span>hsize = int((float(img.size[1]) * float(wpercent)))</span></span>
<span class="line"><span>img = img.resize((basewidth, hsize), Image.ANTIALIAS)</span></span>
<span class="line"><span>img.save(&#39;resized_image.jpg&#39;)</span></span></code></pre></div><p>这几行 Python 代码使用 Pillow 将一张图片 （<code>fullsized_image.jpg</code>） 调整为 300 像素的宽度，宽度在变量 <code>basewidth</code> 中设置，高度则与新的宽度成比例。比例高度的计算方法是：确定 300 像素占原宽度 （<code>img.size[0]</code>） 的百分比，然后将原高度（<code>img.size[1]</code>） 乘以该百分比。所得的高度值保存在变量 <code>hsize</code> 中。</p><p>如果你需要不同的图片宽度，你可以将 <code>basewidth</code> 改为任何其他数字。另外，请注意，因为我想保留全尺寸的图片 （<code>fullsized_image.jpg</code>），因此我将调整后的图片以一个不同的名称 <code>resized_image.jpg</code> 保存。当然，你不必这么做。如果你想，你可以使用相同的文件名将调整后的图片覆盖全尺寸的图片。</p><h3 id="按高度缩放" tabindex="-1">按高度缩放 <a class="header-anchor" href="#按高度缩放" aria-label="Permalink to “按高度缩放”">​</a></h3><p>如果高度是固定的，而宽度是按比例变化的，那也基本差不多，你只需要把东西换一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from PIL import Image</span></span>
<span class="line"><span></span></span>
<span class="line"><span>baseheight = 560</span></span>
<span class="line"><span>img = Image.open(&#39;fullsized_image.jpg&#39;)</span></span>
<span class="line"><span>hpercent = (baseheight / float(img.size[1]))</span></span>
<span class="line"><span>wsize = int((float(img.size[0]) * float(hpercent)))</span></span>
<span class="line"><span>img = img.resize((wsize, baseheight), Image.ANTIALIAS)</span></span>
<span class="line"><span>img.save(&#39;resized_image.jpg&#39;)</span></span></code></pre></div><p>注意 <code>basewidth</code> 现在换成了 <code>baseheight</code>，因为高度是固定的。在第三行中，我们在计算高度百分比，所以我们需要 <code>img.size[1]</code> 而不是 <code>img.size[0]</code>。<code>size</code> 属性是一个元组，包含宽度和高度，单位是像素，<code>size[0]</code> 指的是第一个元组元素，也就是宽度，<code>size[1]</code> 是第二个元素，也就是高度。第 4 行也有这样的切换，<code>size[0]</code> 代表宽度，<code>size[1]</code> 代表高度。</p><hr>`,12)),i("p",null,[s[6]||(s[6]=e("via: ",-1)),a(n,{href:"https://opensource.com/life/15/2/resize-images-python"},{default:t(()=>[...s[5]||(s[5]=[e("https://opensource.com/life/15/2/resize-images-python",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=e("作者：",-1)),a(n,{href:"https://opensource.com/users/dayontwari"},{default:t(()=>[...s[7]||(s[7]=[e("Dayo Ntwari",-1)])]),_:1}),s[12]||(s[12]=e(" 选题：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[e("lujun9972",-1)])]),_:1}),s[13]||(s[13]=e(" 译者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[9]||(s[9]=[e("geekpi",-1)])]),_:1}),s[14]||(s[14]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[e("LCTT",-1)])]),_:1}),s[18]||(s[18]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[e("Linux中国",-1)])]),_:1}),s[19]||(s[19]=e(" 荣誉推出",-1))])])}const c=p(g,[["render",h]]);export{z as __pageData,c as default};
